(()=>{const image=document.querySelector('#ts02-photo'),buttons=[...document.querySelectorAll('[data-ts02-finish]')];if(!image)return;const model=image.alt.split(' ')[0];buttons.forEach(button=>button.addEventListener('click',()=>{const thumbnail=button.querySelector('img');if(!thumbnail)return;image.src=thumbnail.getAttribute('src');image.alt=model+' '+button.dataset.ts02Finish+' glass touch wall switch with app screen';buttons.forEach(other=>other.setAttribute('aria-pressed',String(other===button)))}))})();
